    let a = 77;
    const rnd = () => { a = (a * 1664525 + 1013904223) % 4294967296; return a / 4294967296; };
    const mkStars = (n, big) => Array.from({ length: n }, () => ({ x: Math.round(rnd() * 640) * 2, y: Math.round(rnd() * 720) * 2, r: rnd() > 0.8 ? big : big / 2, c: rnd() > 0.5 ? P.mute : '#ffffff' }));
    const rank = ['1ST', '2ND', '3RD', '4TH', '5TH', '6TH', '7TH', '8TH'], cols = [P.gold, P.soft, P.orange, P.mute, P.mute, P.mute, P.mute, P.mute];
    const rows = (A.rows || []).slice(0, 8).map((r, i) => ({ rank: rank[i], name: esc(cut(r.user, 14)), score: String(r.n).padStart(4, '0'), c: cols[i], d: (i * 0.25).toFixed(2) }));
    const lv = (A.levels || []).slice(0, 3), tot = lv.reduce((s, l) => s + l.ms, 0) || 1, lc = [P.cyan, P.gold, P.pink];
    const levels = lv.map((l, i) => ({ n: i + 1, name: esc(cut(l.name, 20)), time: dur(l.ms), w: Math.max(8, Math.round(l.ms / tot * 100)), c: lc[i], d: (0.2 + i * 0.6).toFixed(1) }));
    const q = (A.quotes && A.quotes.length) ? A.quotes[quoteIdx % A.quotes.length] : { user: issue.studio || '', text: 'Спасибо, что были с нами' };
